// procgen_edim_20261001_searchB.c -- METHOD B (independent re-implementation) of the exhaustive search
// for edge-multiset resolving sets of Q6 (lane procgen_edim, 2026-10-01).
// Normal form B: coordinate 5 is a coordinate of MINIMUM imbalance; after flipping it,
//   S = A x {0} u B x {1}, |A| = a >= b = |B|, a - b = min_i |beta_i(S)|, so |beta_i(S)| >= a - b for i<5.
// A ranges over Aut(Q5)-orbit representatives (file); B over all b-subsets of Q5 meeting the filter,
// generated by a DFS in DEcreasing vertex order. Distances via the projection lemma
// d(e,w) = |(u xor w) minus coordinate i|; keys = 5 levels x 4 bits (level 5 implied);
// duplicate test via a direct-mapped 2^20 stamp array (no hashing). Edges ordered by direction.
// usage: searchB k a repfile [maxdef]   (same output conventions as searchA)
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
static int dEW[192][64];
static uint32_t add_[64][192];
static uint32_t *stamp; static uint32_t gen = 0;
static int K, A, B, DL, MAXDEF = 0, lastdef = 0;
static long long leaves = 0, found = 0, near = 0, nodes = 0;
static uint32_t keys[17][192]; static int beta[5]; static int pick[16]; static uint32_t Amask;
static int leafcheck(const uint32_t *ky) {
  int def = 0; gen++; if (gen == 0) { memset(stamp, 0, 4u << 20); gen = 1; }
  for (int e = 191; e >= 0; e--) { uint32_t x = ky[e]; if (stamp[x] == gen) { if (++def > MAXDEF) return 0; continue; } stamp[x] = gen; }
  lastdef = def; return 1;
}
static void dfs(int depth, int hi) {
  nodes++; int r = B - depth;
  for (int i = 0; i < 5; i++) if (beta[i] - r > -DL && beta[i] + r < DL) return;   // |final beta_i| >= DL impossible
  if (r == 0) {
    leaves++;
    if (leafcheck(keys[depth])) {
      unsigned long long m = Amask; for (int j = 0; j < B; j++) m |= 1ULL << (32 + pick[j]);
      if (lastdef) { near++; printf("NEAR k=%d def=%d mask=%016llx\n", K, lastdef, m); }
      else { found++; printf("RESOLVING k=%d mask=%016llx\n", K, m); }
      fflush(stdout);
    }
    return;
  }
  for (int v = hi - 1; v >= r - 1; v--) {
    for (int e = 0; e < 192; e++) keys[depth + 1][e] = keys[depth][e] + add_[32 + v][e];
    for (int i = 0; i < 5; i++) beta[i] += ((v >> i) & 1) ? -1 : 1;
    pick[depth] = v; dfs(depth + 1, v);
    for (int i = 0; i < 5; i++) beta[i] -= ((v >> i) & 1) ? -1 : 1;
  }
}
int main(int argc, char **argv) {
  if (argc < 4) { fprintf(stderr, "usage: searchB k a repfile [maxdef]\n"); return 1; }
  K = atoi(argv[1]); A = atoi(argv[2]); B = K - A; DL = A - B; if (DL < 0 || K > 15 || K < 1) return 1;
  if (argc > 4) MAXDEF = atoi(argv[4]);
  stamp = calloc(1u << 20, 4);
  int e = 0;
  for (int i = 0; i < 6; i++) for (int u = 0; u < 64; u++) if (!((u >> i) & 1)) {
    for (int w = 0; w < 64; w++) dEW[e][w] = __builtin_popcount((u ^ w) & ~(1 << i));
    e++;
  }
  if (e != 192) return 2;
  for (int w = 0; w < 64; w++) for (int f = 0; f < 192; f++) { int d = dEW[f][w]; add_[w][f] = (d < 5) ? (1u << (4 * d)) : 0u; }
  FILE *fp = fopen(argv[3], "r"); if (!fp) return 3;
  char line[64]; long nrep = 0;
  while (fgets(line, sizeof line, fp)) {
    Amask = (uint32_t)strtoul(line, 0, 16); if (__builtin_popcount(Amask) != A) return 3; nrep++;
    memset(keys[0], 0, sizeof keys[0]); for (int i = 0; i < 5; i++) beta[i] = 0;
    for (int v = 0; v < 32; v++) if ((Amask >> v) & 1) {
      for (int f = 0; f < 192; f++) keys[0][f] += add_[v][f];
      for (int i = 0; i < 5; i++) beta[i] += ((v >> i) & 1) ? -1 : 1;
    }
    dfs(0, 32);
  }
  printf("SUMMARY-B k=%d a=%d b=%d reps=%ld nodes=%lld leaves=%lld found=%lld near=%lld\n", K, A, B, nrep, nodes, leaves, found, near);
  return 0;
}
